<template><ImagePipelineOptions /><ForgeDialog title="Image compressor" description="Batch process images with the existing local Sharp pipeline." eyebrow="WORKSPACE / FILES" wide @close="emit('close')"><div class="image-panel"><div class="image-toolbar"><button class="action-button" @click="batch.selectDir('file')">Add images</button><button class="action-button" @click="batch.selectDir('folder')">Add folder</button><button class="action-button" :disabled="!batch.images.length" @click="batch.images=[]">Clear</button></div><div class="image-settings"><label>Overwrite source<input v-model="batch.rewrite" type="checkbox" /></label><label v-if="!batch.rewrite">Save folder<input :value="batch.saveDir || 'Choose in legacy settings'" readonly /></label><label v-else>Backup folder<input :value="batch.backupDir || 'Choose in legacy settings'" readonly /></label></div><div class="image-list"><article v-for="image in batch.images" :key="image.path"><span><b>{{ image.path }}</b><small>{{ image.ext || 'image' }} · {{ image.width || '—' }}×{{ image.height || '—' }} · {{ image.sizeFormatted || 'reading…' }}</small></span><em>{{ image.status }}</em></article><p v-if="!batch.images.length" class="empty-copy">Add one or more images to begin.</p></div><button class="primary-button" :disabled="!batch.images.length||batch.processing" @click="batch.doProcess()">{{ batch.processing ? 'Processing…' : 'Compress images' }}</button></div><template #footer><span class="website-help">Processing stays local; the existing Sharp configuration is reused.</span></template></ForgeDialog></template>
